using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace RoslynMcp.Core.Refactoring.Utilities;

/// <summary>
/// Recognizes generated and intermediate source files: the documents a build writes (under an
/// <c>obj</c> folder, such as the SDK's <c>*.GlobalUsings.g.cs</c> and <c>*.AssemblyInfo.cs</c>)
/// and files a tool generated (<c>*.g.cs</c>, <c>*.designer.cs</c>, an <c>&lt;auto-generated&gt;</c>
/// header). Tools never edit them, and their declarations are not the user's.
/// </summary>
internal static class GeneratedCode
{
    private static readonly string[] GeneratedSuffixes =
        [".g.cs", ".g.i.cs", ".designer.cs", ".generated.cs"];

    /// <summary>Whether <paramref name="tree"/> is generated or intermediate build output.</summary>
    public static bool IsGenerated(SyntaxTree tree, CancellationToken cancellationToken) =>
        IsGeneratedPath(tree.FilePath) || HasGeneratedHeader(tree, cancellationToken);

    /// <summary>
    /// Whether <paramref name="path"/> names a generated file or lies in an <c>obj</c> folder.
    /// A document without a path is not judged by it.
    /// </summary>
    public static bool IsGeneratedPath(string? path)
    {
        if (string.IsNullOrEmpty(path))
            return false;

        if (GeneratedSuffixes.Any(suffix => path.EndsWith(suffix, StringComparison.OrdinalIgnoreCase)))
            return true;

        return path.Split(['/', '\\'], StringSplitOptions.RemoveEmptyEntries)
            .SkipLast(1)
            .Any(segment => segment.Equals("obj", StringComparison.OrdinalIgnoreCase));
    }

    /// <summary>Whether the comments before the file's first token say it is auto-generated.</summary>
    private static bool HasGeneratedHeader(SyntaxTree tree, CancellationToken cancellationToken)
    {
        var firstToken = tree.GetRoot(cancellationToken).GetFirstToken(includeZeroWidth: true);
        return firstToken.LeadingTrivia.Any(trivia =>
            (trivia.IsKind(SyntaxKind.SingleLineCommentTrivia) || trivia.IsKind(SyntaxKind.MultiLineCommentTrivia)) &&
            (trivia.ToString().Contains("<auto-generated", StringComparison.OrdinalIgnoreCase) ||
             trivia.ToString().Contains("<autogenerated", StringComparison.OrdinalIgnoreCase)));
    }
}
